using System.Collections.Generic;using System.Text;public class Solution{public string AlienOrder(string[]w){var g=new List<int>[26];for(int i=0;i<26;i++)g[i]=new();int[]d=new int[26];bool[]s=new bool[26];foreach(var x in w)foreach(char c in x)s[c-'a']=true;for(int i=0;i+1<w.Length;i++){int j=0,m=System.Math.Min(w[i].Length,w[i+1].Length);while(j<m&&w[i][j]==w[i+1][j])j++;if(j==m){if(w[i].Length>w[i+1].Length)return"";}else{int a=w[i][j]-'a',b=w[i+1][j]-'a';if(!g[a].Contains(b)){g[a].Add(b);d[b]++;}}}var q=new Queue<int>();int cnt=0;for(int i=0;i<26;i++)if(s[i]){cnt++;if(d[i]==0)q.Enqueue(i);}var r=new StringBuilder();while(q.Count>0){int u=q.Dequeue();r.Append((char)('a'+u));foreach(int v in g[u])if(--d[v]==0)q.Enqueue(v);}return r.Length==cnt?r.ToString():"";}}
